import{describe,it,expect}from"vitest";import{execFileSync}from"node:child_process";import{RULES,auditAccessibility}from"../../frontend/scripts/accessibility-check.js";const rule=t=>RULES.find(e=>e.id===t),ids=(t,e)=>rule(e).run(t).length;describe("accessibility-check rules",()=>{it('flags <img> without alt but accepts alt="" for decorative images',()=>{expect(ids('<img src="a.png">',"img-alt")).toBe(1),expect(ids('<img src="a.png" alt="">',"img-alt")).toBe(0),expect(ids('<img src="a.png" alt="Taj Mahal">',"img-alt")).toBe(0)}),it("flags a missing lang attribute on <html>",()=>{expect(ids("<html>","html-lang")).toBe(1),expect(ids('<html lang="en">',"html-lang")).toBe(0)}),it("flags a missing or empty <title>",()=>{expect(ids("<head></head>","page-title")).toBe(1),expect(ids("<title>   </title>","page-title")).toBe(1),expect(ids("<title>Incredible India</title>","page-title")).toBe(0)}),it("flags reused id attributes",()=>{expect(ids('<section id="overview"></section><div id="overview"></div>',"duplicate-id")).toBe(1),expect(ids('<section id="overview"></section><div id="history"></div>',"duplicate-id")).toBe(0)}),it("flags controls with no accessible name",()=>{expect(ids("<button></button>","control-name")).toBe(1),expect(ids("<button><svg></svg></button>","control-name")).toBe(1),expect(ids('<a href="/x"></a>',"control-name")).toBe(1),expect(ids("<button>Search</button>","control-name")).toBe(0),expect(ids('<button aria-label="Clear search"><svg></svg></button>',"control-name")).toBe(0),expect(ids('<button aria-labelledby="lbl"></button>',"control-name")).toBe(0),expect(ids('<a href="/x"><img src="logo.png" alt="Home"></a>',"control-name")).toBe(0),expect(ids('<a name="top"></a>',"control-name")).toBe(0)})}),describe("accessibility-check reporting",()=>{it("reports the line number from the original file, not the stripped one",()=>{const t=['<html lang="en">',"<script>","let x = 1;","<\/script>",'<img src="a.png">'].join("\n"),[e]=rule("img-alt").run(t.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,t=>t.replace(/[^\n]/g," ")));expect(e.line).toBe(5)}),it("ignores markup that only appears inside <script> or comments",()=>{const t="<script>const t = `<button></button>`;<\/script>".replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,t=>t.replace(/[^\n]/g," "));expect(rule("control-name").run(t)).toEqual([]);const e='\x3c!-- <img src="old.png"> --\x3e'.replace(/<!--[\s\S]*?-->/g,t=>t.replace(/[^\n]/g," "));expect(rule("img-alt").run(e)).toEqual([])}),it("finds no violations across the repository",()=>{const{totalScanned:t,violations:e}=auditAccessibility();expect(t).toBeGreaterThan(0),expect(e).toEqual([])})}),describe("accessibility-check CLI",()=>{const t=t=>{try{return{code:0,output:execFileSync("node",["scripts/accessibility-check.js",...t],{encoding:"utf8",stdio:["ignore","pipe","pipe"]})}}catch(t){return{code:t.status,output:`${t.stdout||""}${t.stderr||""}`}}};it("fails loudly when an explicitly named file does not exist",()=>{const{code:e,output:i}=t(["definitely-not-a-real-page.html"]);expect(e).toBe(1),expect(i).toMatch(/not found/i)}),it("scans an existing file that is passed explicitly",()=>{const{code:e,output:i}=t(["login.html"]);expect(e).toBe(0),expect(i).toMatch(/scanned 1 page/)})});